<script setup lang="ts">
import { ref } from 'vue'; import { RouterLink, useRoute, useRouter } from 'vue-router'; import { useAuthStore } from '@/stores/auth'; import { errorMessage } from '@/lib/api'
const auth = useAuthStore(); const router = useRouter(); const route = useRoute(); const mode = ref<'login'|'register'>('login'); const name = ref(''); const email = ref(''); const password = ref(''); const confirmation = ref(''); const error = ref(''); const loading = ref(false)
async function submit() { loading.value=true; error.value=''; try { if (mode.value==='login') await auth.login(email.value,password.value); else await auth.register(name.value,email.value,password.value,confirmation.value); router.push(String(route.query.redirect || '/')) } catch (cause:unknown) { error.value=errorMessage(cause,'Thông tin chưa hợp lệ.') } finally { loading.value=false } }
</script>
<template><section class="card form"><h1>{{ mode==='login' ? 'Đăng nhập' : 'Tạo tài khoản' }}</h1><p class="muted">Quản lý booking sân cầu lông của bạn.</p><form @submit.prevent="submit"><div v-if="mode==='register'" class="field"><label>Họ tên</label><input v-model="name" required /></div><div class="field"><label>Email</label><input v-model="email" type="email" required /></div><div class="field"><label>Mật khẩu</label><input v-model="password" type="password" minlength="8" required /></div><div v-if="mode==='register'" class="field"><label>Nhập lại mật khẩu</label><input v-model="confirmation" type="password" minlength="8" required /></div><p v-if="error" class="error">{{ error }}</p><button class="btn" :disabled="loading">{{ mode==='login' ? 'Đăng nhập' : 'Đăng ký' }}</button></form><RouterLink v-if="mode==='login'" to="/forgot-password" class="muted" style="display:inline-block;margin-top:16px">Quên mật khẩu?</RouterLink><p><button class="link-button" style="color:#0e6b50" @click="mode=mode==='login'?'register':'login'">{{ mode==='login' ? 'Chưa có tài khoản? Đăng ký' : 'Đã có tài khoản? Đăng nhập' }}</button></p></section></template>
